CREATE TABLE soap_notes (id VARCHAR(80) PRIMARY KEY, tenant_id UUID NOT NULL, examination_id VARCHAR(80) NOT NULL REFERENCES examinations(id) ON DELETE RESTRICT, subjective TEXT NOT NULL, objective TEXT NOT NULL, assessment TEXT NOT NULL, plan TEXT NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by UUID NOT NULL, signed_at TIMESTAMPTZ(6), signed_by UUID, amended_at TIMESTAMPTZ(6), CONSTRAINT soap_notes_tenant_examination_unique UNIQUE(tenant_id, examination_id));
ALTER TABLE soap_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY soap_notes_tenant_isolation ON soap_notes USING (current_setting('app.is_superadmin',true)='true' OR tenant_id::text=current_setting('app.tenant_id',true)) WITH CHECK (current_setting('app.is_superadmin',true)='true' OR tenant_id::text=current_setting('app.tenant_id',true));
CREATE TABLE soap_amends (id VARCHAR(80) PRIMARY KEY, tenant_id UUID NOT NULL, original_soap_id VARCHAR(80) NOT NULL REFERENCES soap_notes(id) ON DELETE RESTRICT, examination_id VARCHAR(80) NOT NULL REFERENCES examinations(id) ON DELETE RESTRICT, reason TEXT NOT NULL, subjective TEXT NOT NULL, objective TEXT NOT NULL, assessment TEXT NOT NULL, plan TEXT NOT NULL, amended_by UUID NOT NULL, amended_at TIMESTAMPTZ(6) NOT NULL, previous_signed_at TIMESTAMPTZ(6), previous_signed_by UUID);
CREATE INDEX soap_amends_tenant_exam_at_idx ON soap_amends(tenant_id, examination_id, amended_at);
ALTER TABLE soap_amends ENABLE ROW LEVEL SECURITY;
CREATE POLICY soap_amends_tenant_isolation ON soap_amends USING (current_setting('app.is_superadmin',true)='true' OR tenant_id::text=current_setting('app.tenant_id',true)) WITH CHECK (current_setting('app.is_superadmin',true)='true' OR tenant_id::text=current_setting('app.tenant_id',true));
